gUI(){return"\u041d\u0435\u0442. \u0417\u043d\u0430\u043a \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043f\u0440\u044f\u043c\u043e, \u043d\u0430\u043b\u0435\u0432\u043e \u0438 \u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442."},
gUL(){return"\u041f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u0435 \u043d\u0443\u0436\u043d\u043e \u043e\u0431\u044a\u0435\u0445\u0430\u0442\u044c \u0441\u043f\u0440\u0430\u0432\u0430?"},
gUK(){return"\u0414\u0430. \u041e\u0431\u044a\u0435\u0437\u0434 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0441 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u043e\u0439 \u0441\u0442\u0440\u0435\u043b\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b."},
gUN(){return"\u041c\u043e\u0436\u043d\u043e \u043e\u0431\u044a\u0435\u0445\u0430\u0442\u044c \u043f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u043b\u0435\u0432\u0430, \u0435\u0441\u043b\u0438 \u0432\u0441\u0442\u0440\u0435\u0447\u043d\u044b\u0445 \u043d\u0435\u0442?"},
